package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct { // 01 SCHED-REC, 16 bytes
	ScAcct  string          // PIC X(4) @0 len=4
	ScPrin  decimal.Decimal // PIC 9(5)V99 @4 len=7
	ScRate  decimal.Decimal // PIC 9(2)V99 @11 len=4
	ScYears int64           // PIC 9(1) @15 len=1
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsBal decimal.Decimal = decimal.NewFromInt(0) // PIC 9(8)V99 len=10 = 0
var WsYear int64 = 0         // PIC 99 len=2 = 0
var WsCount int64 = 0        // PIC 99 len=2 = 0
var WsBalEd string           // PIC ZZ,ZZZ,ZZ9.99 len=13

var curRec SchedRec
var schedFile *os.File
var schedScanner *bufio.Scanner

func InputDone() bool {
	return WsEofFlag == "Y"
}

func parseImplied(s string, scale int32) decimal.Decimal {
	if strings.TrimSpace(s) == "" {
		return decimal.NewFromInt(0)
	}
	t := strings.TrimSpace(s)
	// remove embedded spaces (treat as zero)
	t = strings.ReplaceAll(t, " ", "")
	if t == "" {
		return decimal.NewFromInt(0)
	}
	// allow optional sign
	n, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		// fallback: keep digits only
		var b strings.Builder
		for _, ch := range t {
			if ch >= '0' && ch <= '9' {
				b.WriteRune(ch)
			}
		}
		if b.Len() == 0 {
			return decimal.NewFromInt(0)
		}
		n, _ = strconv.ParseInt(b.String(), 10, 64)
	}
	return decimal.New(n, -scale)
}

func parseInt1(s string) int64 {
	if strings.TrimSpace(s) == "" {
		return 0
	}
	t := strings.TrimSpace(s)
	t = strings.ReplaceAll(t, " ", "")
	if t == "" {
		return 0
	}
	n, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		return 0
	}
	return n
}

func maskBal(v decimal.Decimal) decimal.Decimal {
	c := v.Shift(2).Truncate(0).IntPart()
	const modCents int64 = 10000000000 // 10^10 = 10^8 * 100
	m := c % modCents
	return decimal.New(m, -2)
}

func formatBalEd(v decimal.Decimal) string {
	av := v.Abs()
	cents := av.Shift(2).Truncate(0).IntPart()
	intPart := cents / 100
	frac := cents % 100
	if intPart < 0 {
		intPart = -intPart
	}
	if frac < 0 {
		frac = -frac
	}
	intPart = intPart % 100000000
	var d [8]int64
	tmp := intPart
	for i := 7; i >= 0; i-- {
		d[i] = tmp % 10
		tmp /= 10
	}
	fracTens := frac / 10
	fracOnes := frac % 10
	out := make([]byte, 13)
	seen := false
	// p0
	if d[0] != 0 {
		out[0] = byte('0' + d[0])
		seen = true
	} else {
		out[0] = ' '
	}
	// p1
	if d[1] != 0 {
		out[1] = byte('0' + d[1])
		seen = true
	} else {
		if seen {
			out[1] = '0'
		} else {
			out[1] = ' '
		}
	}
	// comma1
	if seen {
		out[2] = ','
	} else {
		out[2] = ' '
	}
	// p2
	if d[2] != 0 {
		out[3] = byte('0' + d[2])
		seen = true
	} else {
		if seen {
			out[3] = '0'
		} else {
			out[3] = ' '
		}
	}
	// p3
	if d[3] != 0 {
		out[4] = byte('0' + d[3])
		seen = true
	} else {
		if seen {
			out[4] = '0'
		} else {
			out[4] = ' '
		}
	}
	// p4
	if d[4] != 0 {
		out[5] = byte('0' + d[4])
		seen = true
	} else {
		if seen {
			out[5] = '0'
		} else {
			out[5] = ' '
		}
	}
	// comma2
	if seen {
		out[6] = ','
	} else {
		out[6] = ' '
	}
	// p5
	if d[5] != 0 {
		out[7] = byte('0' + d[5])
		seen = true
	} else {
		if seen {
			out[7] = '0'
		} else {
			out[7] = ' '
		}
	}
	// p6
	if d[6] != 0 {
		out[8] = byte('0' + d[6])
		seen = true
	} else {
		if seen {
			out[8] = '0'
		} else {
			out[8] = ' '
		}
	}
	// p7 is 9, always prints
	out[9] = byte('0' + d[7])
	// dot
	out[10] = '.'
	out[11] = byte('0' + fracTens)
	out[12] = byte('0' + fracOnes)
	return string(out)
}

func MainPara() {
	var err error
	schedFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	schedScanner = bufio.NewScanner(schedFile)
	// allow long lines; default is fine for 16 bytes but enlarge anyway
	const maxCap = 1024 * 1024
	buf := make([]byte, 0, 64*1024)
	schedScanner.Buffer(buf, maxCap)
	ReadPara()
	for !InputDone() {
		ProcessPara()
	}
	schedFile.Close()
	// DISPLAY "SCHEDULES: " WS-COUNT (PIC 99 zero-padded 2)
	c := ((WsCount % 100) + 100) % 100
	fmt.Printf("SCHEDULES: %02d\n", c)
}

func ReadPara() {
	if schedScanner.Scan() {
		line := schedScanner.Text()
		if len(line) < 16 {
			line += strings.Repeat(" ", 16-len(line))
		} else if len(line) > 16 {
			line = line[:16]
		}
		curRec.ScAcct = line[0:4]
		curRec.ScPrin = parseImplied(line[4:11], 2)
		curRec.ScRate = parseImplied(line[11:15], 2)
		curRec.ScYears = parseInt1(line[15:16])
	} else {
		if err := schedScanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	WsBal = maskBal(curRec.ScPrin)
	// PERFORM VARYING WS-YEAR FROM 1 BY 1 UNTIL WS-YEAR > SC-YEARS
	WsYear = 1
	for ; !(WsYear > curRec.ScYears); WsYear++ {
		factor := decimal.NewFromInt(1).Add(curRec.ScRate.Shift(-2))
		raw := WsBal.Mul(factor)
		rounded := raw.Round(2)
		WsBal = maskBal(rounded)
		WsBalEd = formatBalEd(WsBal)
		y := ((WsYear % 100) + 100) % 100
		fmt.Printf("%s Y%02d %s\n", curRec.ScAcct, y, WsBalEd)
	}
	WsBalEd = formatBalEd(WsBal)
	fmt.Printf("%s FINAL %s\n", curRec.ScAcct, WsBalEd)
	WsCount = (WsCount + 1) % 100
	ReadPara()
}

func main() {
	MainPara()
}
